// produção declarada: qtd pendente e qtd produzida da linha
// alocações do SMKT consomem saldo do PV na carteira (modelo WARD: produto pronto atende o PV)
function smktAlocadoEm(pv, cod){
  return smktAlocs().filter(function(x){ return x.cod===cod && String(x.pv)===String(pv); }).reduce(function(a,x){ return a+x.qtd; },0);
}
// O movimento para o SMKT é consumo da programação. Alocar depois em um PV
// apenas muda a destinação do pronto — não desconta a mesma unidade duas vezes.
function smktManualTotal(cod){
  return smktEntradas().filter(function(x){ return x.cod===cod && String(x.origem||'').indexOf('prog:')!==0; }).reduce(function(a,x){ return a+x.qtd; },0);
}
function smktProgramTotal(cod){
  // entradas com origem 'prog:' = entrada criada pela alocação SMKT no card principal
  return smktEntradas().filter(function(x){ return x.cod===cod && String(x.origem||'').indexOf('prog:')===0; }).reduce(function(a,x){ return a+x.qtd; },0);
}
function declaradoTotal(cod){
  return DATA.rows.filter(function(x){ return x.codigo===cod && x.prod; }).reduce(function(a,x){ return a+Math.min(x.prod.qtd,x.qtd); },0);
}
function progFuturoTotal(cod){
  // programado a partir de HOJE (futuro) — passado é histórico e não bloqueia a programação
  const hj=new Date(); const hojeISO=hj.getFullYear()+'-'+String(hj.getMonth()+1).padStart(2,'0')+'-'+String(hj.getDate()).padStart(2,'0');
  return declDaUnid().filter(function(d){ return d.status!=='Cancelado'&&d.cod===cod&&Number(d.qtd)>0&&progIso(d.data)>=hojeISO; }).reduce(function(s,d){ return s+Number(d.qtd); },0);
}
function disponivelProg(cod){
  // saldo com PV − programado futuro − realizado (produção declarada/SMKT extra) — o que ainda cabe em PV
  let done=0,sm=0; try{ done=declaradoTotal(cod); }catch(e){} try{ sm=Math.max(0,Number(smktExtraTotal(cod))||0); }catch(e){}
  const saldoPv=DATA.rows.filter(function(r){ return r.codigo===cod; }).reduce(function(s,r){ return s+(Number(r.qtd)||0); },0);
  return Math.max(0, saldoPv - progFuturoTotal(cod) - done - sm);
}
function smktExtraTotal(cod){
  // produção declarada já foi debitada em r.prod; só o excedente é adicional.
  return smktManualTotal(cod) + Math.max(0, smktProgramTotal(cod)-declaradoTotal(cod));
}
function smktExtraForRow(r){
  let restante = smktExtraTotal(r.codigo);
  if(restante<=0) return 0;
  for(let i=0;i<DATA.rows.length;i++){
    const x = DATA.rows[i];
    if(x.codigo!==r.codigo) continue;
    const base = x.prod ? Math.max(0, x.qtd-x.prod.qtd) : x.qtd;
    const uso = Math.min(restante, base);
    if(x===r) return uso;
    restante -= uso;
    if(restante<=0) return 0;
  }
  return 0;
}
function qtdPend(r){
  const base = r.prod ? Math.max(0, r.qtd-r.prod.qtd) : r.qtd;
  return Math.max(0, base-smktExtraForRow(r));
}
function qtdProd(r){
  const declarado = r.prod ? Math.min(r.prod.qtd,r.qtd) : 0;
  return Math.min(r.qtd, declarado+smktExtraForRow(r));
}
function vPend(r){ return r.vtot*(r.qtd ? qtdPend(r)/r.qtd : 0); }
function vProd(r){ return r.vtot*(r.qtd ? qtdProd(r)/r.qtd : 0); }
