let apQ = '';
// data sugerida: 1º dia útil livre a partir de amanhã (carga = declarações existentes + rascunho)
function apSugerirData(){
  const hoje = new Date(); hoje.setDate(hoje.getDate()+1);
  const carga = {};
  declDaUnid().forEach(function(d){
    if(d.status==='Cancelado'||!d.data||Number(d.qtd)<=0) return;
    carga[d.data]=(carga[d.data]||0)+Number(d.qtd);
  });
  const med = Object.keys(carga).length ? Object.keys(carga).reduce(function(a,k){return a+carga[k];},0)/Object.keys(carga).length : 0;
  for(let i=0;i<30;i++){
    const d=new Date(hoje); d.setDate(hoje.getDate()+i);
    const w=d.getDay(); if(w===0||w===6) continue;
    const iso=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    if((carga[iso]||0) <= med*1.5) return iso;
  }
  return hoje.toISOString().slice(0,10);
}
