// ==================== REALOCAÇÃO MANUAL DE PV (06/10, v0.0.235) ====================
// Regra Dante: a mudança manual de alocação só entre PVs que TÊM saldo a entregar do produto.
// A produção não muda — muda o DESTINO das unidades de um PV de origem para um PV de destino.
// Registro: localStorage 'rlpv|<cod>|<de>|<para>' = {qtd, quando} — consultado por progBuildFromDecls.
function rlpvRegs(cod){
  try{ const raw=JSON.parse(localStorage.getItem('rlpv|'+String(cod))||'[]'); return Array.isArray(raw)?raw:[]; }catch(e){ return []; }
}
function rlpvSave(cod, regs){
  try{ localStorage.setItem('rlpv|'+String(cod), JSON.stringify(regs||[])); }catch(e){}
  try{ rlpvCache = rlpvAllLoad(); }catch(e){}
  if(window.ANDON_SYNC&&window.ANDON_SYNC.connected()){
    localStorage.setItem('andon|rlpv-rev',String(Date.now()));
    try{ window.ANDON_SYNC.pushRlpv(String(cod), regs||[]).catch(function(){}); }catch(e){}
  }
}
// saldo a entregar do PV (linha da carteira) MENOS o que já foi realocado para fora dele
function pvSaldoAposRealoc(pv, cod){
  const rs = DATA.rows.filter(function(r){ return String(r.pv)===String(pv) && r.codigo===cod; });
  const saldo = rs.reduce(function(a,r){ return a+(Number(r.qtd)||0); },0);
  const fora = rlpvRegs(cod).filter(function(x){ return String(x.de)===String(pv); }).reduce(function(a,x){ return a+(Number(x.qtd)||0); },0);
  return {saldo:saldo, fora:fora, livre:Math.max(0, saldo-fora)};
}
function pvRealocadoDe(pv, cod){
  return rlpvRegs(cod).filter(function(x){ return String(x.para)===String(pv); }).reduce(function(a,x){ return a+(Number(x.qtd)||0); },0);
}
// PVs com saldo a entregar do produto (destinos possíveis) — regra Dante
function rlpvDestinos(cod, pvOrigem){
  const regs = rlpvRegs(cod);
  const agg = {};
  DATA.rows.forEach(function(r){
    if(r.codigo!==cod) return;
    const k = String(r.pv);
    const o = agg[k] = agg[k] || {pv:k, cli:r.cliente, emp:r.empresa, saldo:0, iso:r.iso, atr:false};
    o.saldo += Number(r.qtd)||0;
    if(r.iso && (!o.iso || r.iso<o.iso)) o.iso = r.iso;
    if(r.semana==='ATRASADO') o.atr = true;
  });
  const de = String(pvOrigem);
  return Object.values(agg).filter(function(o){ return o.pv!==de; })
    .map(function(o){
      const para = regs.filter(function(x){ return String(x.para)===o.pv; }).reduce(function(a,x){ return a+(Number(x.qtd)||0); },0);
      const fora = regs.filter(function(x){ return String(x.de)===o.pv; }).reduce(function(a,x){ return a+(Number(x.qtd)||0); },0);
      return Object.assign(o, {livre: Math.max(0, o.saldo-fora), realoc: para});
    })
    .filter(function(o){ return o.livre>0; })
    .sort(function(a,b){ return a.iso.localeCompare(b.iso); });
}
function pvTagDe(cod, pv){
  const o = DATA.rows.find(function(r){ return String(r.pv)===String(pv) && r.codigo===cod; });
  return o ? (String(o.cliente||'').slice(0,26)) : '';
}
