function progBuildFromDecls(){
  if(!DATA.progSemana)return;
  const avail={}; DATA.rows.forEach(function(r){const k=r.codigo+'|'+r.pv+'|'+r.empresa;avail[k]=(avail[k]||0)+Number(r.qtd||0);});
  const dias=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado']; const out=[];
  window.fosseisCache=[];
  declDaUnid().forEach(function(d){if(d.status==='Cancelado'||!d.cod||!d.data||Number(d.qtd)<=0)return;
    const dt=new Date(d.data+'T12:00:00'),day=dias[dt.getDay()],date=d.data.slice(8,10)+'/'+d.data.slice(5,7);let left=Number(d.qtd);
    let cand=DATA.rows.filter(function(r){return r.codigo===d.cod&&(!d.pv||String(r.pv)===String(d.pv));}).sort(function(a,b){return a.iso.localeCompare(b.iso);});
    // POKA-YOKE: declaração sem NENHUM saldo correspondente na carteira = fóssil (PV já faturado ou inexistente) — não vira linha fantasma
    if(!cand.length){ window.fosseisCache.push({cod:d.cod,qtd:Number(d.qtd),pv:d.pv||'—',data:d.data,motivo:d.pv?('PV '+d.pv+' faturado/sem saldo — NF já saiu?'):'código sem saldo na carteira'}); return; }
    const prodIso=d.data; // coleta real parte da PRODUÇÃO declarada (1º DU após), não da entrega
    cand.forEach(function(r){const k=r.codigo+'|'+r.pv+'|'+r.empresa,q=Math.min(left,avail[k]||0);if(q<=0)return;
      // chegada prevista = coleta (1º DU após a produção) + trânsito; atrasado quando chega DEPOIS da entrega
      let atrasado = r.semana==='ATRASADO';
      let chegTxt;
      const cid=cidadeDeOrig(r.cliente, d.local);
      const tab=d.local==='V'?TRANSITO_VINHEDO:TRANSITO;
      const tdu=cid?tab[cid][0]:null;
      if(tdu){
        const p=new Date(prodIso+'T12:00:00');
        const coleta=addDU(p,1), cheg=addDU(coleta,tdu);
        chegTxt=dtBR(isoD(cheg))+(cid?' · '+cid:'');
        const de=new Date(r.iso+'T12:00:00');
        if(cheg>de)atrasado=true;
      } else if(d.local==='V'){ chegTxt='fora da tabela'; }
      else { chegTxt=dtBR(r.iso)+' · fora da tabela'; }
      out.push({dia:day,data:date,cod:d.cod,desc:r.desc,qtd:q,pv:String(r.pv),cli:r.cliente,emp:r.empresa,vtot:r.qtd?r.vtot*q/r.qtd:0,sit:atrasado?'ATRASADO':'em dia',cheg:chegTxt,local:d.local==='V'?'Vinhedo':'Curitiba',firme:r.iso,cidade:cid||'',prog_id:d.id||'',obs:d.obs||'',status:d.status||'Planejado'});avail[k]-=q;left-=q;});
    if(left>0){const vu=(cand.length&&cand[0].qtd)?(cand[0].vtot/cand[0].qtd):0;out.push({dia:day,data:date,cod:d.cod,desc:descDe(d.cod),qtd:left,pv:d.pv||'—',cli:'',emp:'',vtot:vu*left,sit:'Sem PV associado',cheg:'—',local:d.local==='V'?'Vinhedo':'Curitiba',semPv:true,prog_id:d.id||'',obs:d.obs||'',status:d.status||'Planejado'});}
  });
  // REALOCAÇÃO MANUAL DE PV (v0.0.235): move qtd entre PVs da MESMA declaração (mesma
  // data+produto) — a produção continua igual, muda só o destino. Regra Dante: só entre
  // PVs com saldo a entregar do produto. PV de origem pode zerar (fica sem linha).
  try{
    const porData={};
    const novos=[];
    out.forEach(function(a){ if(a.semPv||!a.pv||a.pv==='—')return; const k=a.data+'|'+a.cod; (porData[k]=porData[k]||[]).push(a); });
    Object.keys(rlpvCache||{}).forEach(function(cod){
      (rlpvCache[cod]||[]).forEach(function(g){
        const list=porData[g.data+'|'+g.cod]; if(!list||!list.length) return;
        let need=Number(g.qtd)||0;
        for(let i=list.length-1;i>=0&&need>0;i--){
          const a=list[i];
          if(String(a.pv)!==String(g.de)) continue;
          const t=Math.min(need,a.qtd);
          if(t<=0) continue;
          const vu=a.qtd>0?(a.vtot/a.qtd):(vuDe(a.cod)||0);
          a.qtd-=t; need-=t;
          a.vtot=vu*a.qtd;
          const dest=list.find(function(x){ return String(x.pv)===String(g.para); });
          if(dest){ const vu2=dest.qtd>0?(dest.vtot/dest.qtd):vu; dest.qtd+=t; dest.vtot=vu2*dest.qtd; }
          else { novos.push({dia:a.dia,data:a.data,cod:a.cod,desc:a.desc,qtd:t,pv:String(g.para),cli:pvTagDe(a.cod,g.para),emp:'',vtot:t*(vuDe(a.cod)||0),sit:a.sit,cheg:'—',local:a.local,firme:a.firme||'',cidade:'',prog_id:a.prog_id||'',obs:(a.obs||'')+' · realocado de PV '+g.de,status:a.status||'Planejado'}); }
          if(a.qtd<=0.0001) list.splice(i,1);
        }
      });
    });
    if(novos.length) novos.forEach(function(n){ out.push(n); });
  }catch(e){}
  DATA.progSemana.dias=out;
}

// ---- FIRME: enviar produto da tabela semanal para a Programação firme (v0.0.213) ----
// v0.0.460 (Dante 20/10): ciclo do firme no card semanal —
//   programou firme na semana → SAI da qtd pendente (badge FIRME);
//   não executou (cancelou/apagou) → VOLTA a somar como pendência;
//   passou da data/semana sem executar → VOLTA p/ pendência + FIRME ATRASADA + ATRASADO.
window.firmeDaSemana = function(label){
  const seg = semanaSegunda(label);
  const fim = seg ? isoD(addDU(new Date(seg+'T12:00:00'),4)) : null;
  const hj = isoD(new Date());
  const firmeSem={}, atrFirme={};
  if(seg&&fim){
    // card semanal é AGREGADO (duas fábricas) — firme de qualquer unidade desconta aqui
    (Array.isArray(declDraft)?declDraft:[]).forEach(function(d){
      // Realizado NÃO entra: já conta como produção (débito FIFO) — descontar de novo seria dupla contagem
      if(d.status==='Cancelado'||d.status==='Realizado'||!d.data||Number(d.qtd)<=0) return;
      const di=progIso(d.data); if(!di) return;
      if(di<seg||di>fim) return;
      if(di>=hj) firmeSem[d.cod]=(firmeSem[d.cod]||0)+Number(d.qtd);
      else atrFirme[d.cod]=(atrFirme[d.cod]||0)+Number(d.qtd);
    });
  }
  return {firmeSem:firmeSem, atrFirme:atrFirme, seg:seg, fim:fim};
};
