  function isoOf(dt){const p=String(dt).split('/');if(p.length===3)return p[2]+'-'+p[1]+'-'+p[0];if(p.length===2)return String(hj.getFullYear())+'-'+p[1]+'-'+p[0];return dt;}
  const dias = [...new Map(DATA.progSemana.dias.map(function(a){return [a.data+'|'+a.dia,a];})).values()].sort(function(a,b){return isoOf(a.data).localeCompare(isoOf(b.data));});
