  if(dow>=5){ segDate=new Date(hj); segDate.setDate(segDate.getDate()+(7-dow)); } // sáb/dom: próxima segunda
  const segIso=segDate.getFullYear()+'-'+String(segDate.getMonth()+1).padStart(2,'0')+'-'+String(segDate.getDate()).padStart(2,'0');
  // ---- semanas disponíveis: TODAS as semanas do ano (S01-S52/53) + as que têm declaração ----
