  const semanasMap={};
  dias.forEach(function(x){const p=isoOf(x.data).split('-');const d0=new Date(Number(p[0]),Number(p[1])-1,Number(p[2]));const dw=(d0.getDay()+6)%7;const seg=new Date(d0);seg.setDate(seg.getDate()-dw);const si=seg.getFullYear()+'-'+String(seg.getMonth()+1).padStart(2,'0')+'-'+String(seg.getDate()).padStart(2,'0');(semanasMap[si]=semanasMap[si]||[]).push(x);});
