  for(let i=0;i<53;i++){const d=new Date(seg1);d.setDate(d.getDate()+i*7);if(d.getFullYear()>anoHj)break;const si=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');if(!semanasMap[si])semanasMap[si]=[];}
