// DESFAZER: reverte um evento específico do histórico (por índice) — corrige qualquer erro.
function smktUndo(evIdx){
 smktEnsureMigrated();
 const h=smktHistory();
 let i=(typeof evIdx==='number')?evIdx:0;
 if(h[i]&&h[i].undone){document.getElementById('smUndoInfo').textContent='Este evento já foi desfeito.';return;}
 if(i>=h.length||!h[i]){document.getElementById('smUndoInfo').textContent='Nada a desfazer.';return;}
 const ev=h[i];
 const ents=smktEntradas();
 if(ev.event==='Entrada via programação (destino SMKT)'){
  // desfazer a entrada: remove as unidades do saldo SOMANDO as que voltaram por
  // desfazer de alocação/retirada (ledger consistente — nunca deixa resíduo).
  const k='prog:'+String(ev.cod)+'|'+(String(ev.motivo||'').split('dia ')[1]||'');
  let rest=Number(ev.qtd)||0;
  for(let j=ents.length-1;j>=0&&rest>0;j--){if(String(ents[j].origem||'')===k){const t=Math.min(rest,Number(ents[j].qtd)||0);ents[j].qtd-=t;rest-=t;}}
  for(let j=ents.length-1;j>=0&&rest>0;j--){if(String(ents[j].origem||'')==='undo'&&String(ents[j].cod)===String(ev.cod)){const t=Math.min(rest,Number(ents[j].qtd)||0);ents[j].qtd-=t;rest-=t;}}
  for(let j=0;j<ents.length&&rest>0;j++){if(String(ents[j].cod)===String(ev.cod)){const t=Math.min(rest,Number(ents[j].qtd)||0);ents[j].qtd-=t;rest-=t;}}
  const rem=ents.filter(function(x){return Number(x.qtd)>0.0001;});
  smktSave(rem,[]);
  if(rest>0.0001){document.getElementById('smUndoInfo').textContent='Parcial: '+NF.format(Number(ev.qtd)-rest)+' de '+NF.format(ev.qtd)+' un (o resto já saiu por alocação/retirada).';}
  else{document.getElementById('smUndoInfo').textContent='Desfeita a entrada de '+ev.cod+' ×'+NF.format(ev.qtd)+'.';}
  ev.undone=true;ev.motivo=(ev.motivo||'')+' [DESFEITO]';
 }else if(ev.event==='Entrada manual'){
  let rest=Number(ev.qtd)||0;
  for(let j=0;j<ents.length&&rest>0;j++){if(String(ents[j].cod)===String(ev.cod)){const t=Math.min(rest,Number(ents[j].qtd)||0);ents[j].qtd-=t;rest-=t;}}
  smktSave(ents.filter(function(x){return Number(x.qtd)>0.0001;}),[]);
  if(rest>0.0001){document.getElementById('smUndoInfo').textContent='Parcial: '+NF.format(Number(ev.qtd)-rest)+' de '+NF.format(ev.qtd)+' un (o resto já saiu por alocação/retirada).';}
  else{document.getElementById('smUndoInfo').textContent='Desfeita a entrada de '+ev.cod+' ×'+NF.format(ev.qtd)+'.';}
  ev.undone=true;ev.motivo=(ev.motivo||'')+' [DESFEITO]';
 }else if(ev.event==='Alocado em PV'){
  // devolve as unidades À ENTRADA ORIGINAL do produto (não cria entrada órfã) —
  // assim desfazer a entrada depois remove tudo de forma consistente.
  const e2=smktEntradas();let devolvido=false;
  for(let j=0;j<e2.length&&!devolvido;j++){if(String(e2[j].cod)===String(ev.cod)){e2[j].qtd=(Number(e2[j].qtd)||0)+(Number(ev.qtd)||0);devolvido=true;}}
  if(!devolvido)e2.push({cod:String(ev.cod),qtd:Number(ev.qtd)||0,origem:'undo',data:new Date().toLocaleDateString('pt-BR')});
  smktSave(e2,[]);
  document.getElementById('smUndoInfo').textContent='Desfeita a alocação: '+ev.cod+' ×'+NF.format(ev.qtd)+' voltou ao saldo (PV '+ev.pv+' desalocado).';
  ev.undone=true;ev.motivo=(ev.motivo||'')+' [DESFEITO]';
 }else if(ev.event==='Retirada manual'){
  const e2=smktEntradas();let devolvido=false;
  for(let j=0;j<e2.length&&!devolvido;j++){if(String(e2[j].cod)===String(ev.cod)){e2[j].qtd=(Number(e2[j].qtd)||0)+(Number(ev.qtd)||0);devolvido=true;}}
  if(!devolvido)e2.push({cod:String(ev.cod),qtd:Number(ev.qtd)||0,origem:'undo',data:new Date().toLocaleDateString('pt-BR')});
  smktSave(e2,[]);
  document.getElementById('smUndoInfo').textContent='Desfeita a retirada: '+ev.cod+' ×'+NF.format(ev.qtd)+' voltou ao saldo.';
  ev.undone=true;ev.motivo=(ev.motivo||'')+' [DESFEITO]';
 }else if(ev.event==='Consumo via NF'){
  document.getElementById('smUndoInfo').textContent='Consumo via NF '+ev.nf+' não é reversível aqui — a NF é fato do MaxiProd. Use "Alocar" para devolver ao PV ou "+ Entrada no SMKT" para repor.';
  return;
 }else{
  document.getElementById('smUndoInfo').textContent='Evento "'+ev.event+'" não tem desfazer automático.';
  return;
 }
 smktHistorySave(h);
 renderSmkt();renderProgTabela();
}
// desfazer individual: delegação no tbody do histórico
renderSmkt();

// ==================== CARD NFs EMITIDAS (método Compass) ====================
function renderNF(){
  const nb = DATA.nfBaixadas;
  const card = document.getElementById('cardNF');
  if(!nb || !nfLista().length){ card.style.display='none'; return; }
  card.style.display='';
  document.getElementById('trhN').innerHTML = '<th>NF</th><th>Emissão</th><th>Empresa</th><th>Itens baixados (PV · produto · qtd)</th>';
  document.getElementById('tbbN').innerHTML = nfLista().sort(function(a,b){ return (b.data||'').localeCompare(a.data||''); }).map(function(n){
    const itens = (Array.isArray(n.itens)?n.itens:[]).map(function(i){
      const ds=String(i.desc||descDe(i.cod)||'').slice(0,34);
      return '<span style="white-space:nowrap;margin:2px 6px 2px 0;display:inline-block"><b class="pvtag">'+i.pv+'</b> '+i.cod+' ×'+NF.format(i.qtd)+' <span class="dsc" style="color:var(--mut)">'+ds+'</span></span>';
    }).join('');
    return '<tr><td><b>'+n.nf+'</b></td><td>'+dtBR(n.data)+'</td><td>'+n.emp+'</td><td>'+itens+'</td></tr>';
  }).join('');
}
renderNF();

function renderSug(){
  const card = document.getElementById('cardSug');
  const sug = sugestoesSemana();
  if(!sug.length){ card.style.display='none'; return; }
  card.style.display='';
  document.getElementById('trhG').innerHTML = '<th>Produto</th><th>PV / Cliente</th><th>Qtd</th><th>Coleta máx.</th><th>Produzir até</th><th>Entrega cliente</th><th>Alocação (se aceitar)</th><th>Executado?</th><th>Qtd executada</th><th></th>';
  let tq=0, te=0;
  const diasSem = ['Segunda','Terça','Quarta','Quinta','Sexta'];
  const rowsHtml = sug.map(function(s, ix){
    const r = s.row;
    const ex = getExec(r) || {ok:false, qtd:0};
    tq += r.qtd; te += ex.qtd||0;
    const rig = r.rig ? ' <span class="tagR">RÍGIDA '+r.rig.data+'</span>' : '';
    const divData = (r.rig && r.rig.iso !== r.iso) ? dtBR(r.iso)+' → ' : '';
    // alocação sugerida: produzir até s.prod → aloco no dia s.prod (ou hoje se já passou)
    const hoje0 = new Date(); hoje0.setHours(0,0,0,0);
    const prodD = new Date(s.prod); prodD.setHours(12,0,0,0);
    const diaAloc = prodD < hoje0 ? hoje0 : prodD;
    const dw = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][diaAloc.getDay()];
    const aloc = ex.rl ? '→ '+ex.rl.slice(8,10)+'/'+ex.rl.slice(5,7) : dw+' · '+brD(diaAloc);
    return '<tr class="exrow '+(ex.ok?'exOK':'')+'" data-ix="'+ix+'">'+
      '<td><div class="cod">'+r.codigo+'</div><div class="dsc">'+r.desc.slice(0,40)+'</div></td>'+
      '<td><b>'+r.pv+'</b> '+r.cliente.slice(0,24)+'</td>'+
      '<td class="num"><b>'+NF.format(r.qtd)+'</b></td>'+
      '<td>'+brD(s.coleta)+'</td>'+
      '<td>'+brD(s.prod)+'</td>'+
      '<td>'+divData+dtBR(s.alvoIso)+rig+'</td>'+
      '<td><span class="tagS">'+aloc+'</span></td>'+
      '<td class="exec"><input type="checkbox" data-x="ok" '+(ex.ok?'checked':'')+'></td>'+
      '<td class="exec"><input type="number" min="0" max="'+r.qtd+'" value="'+(ex.qtd||'')+'" placeholder="0" data-x="qtd"></td>'+
      '<td class="exec"><button class="exRl" data-x="rl" title="Realocar saldo (qtd − executada) para o próximo dia útil">Realocar ↦</button>'+(ex.rl?'<div style="font-size:10px;color:#92400e;font-weight:700;margin-top:3px">→ '+ex.rl.slice(8,10)+'/'+ex.rl.slice(5,7)+' ('+NF.format(ex.saldo)+' un)</div>':'')+'</td></tr>';
  }).join('');
  document.getElementById('tbbG').innerHTML = rowsHtml;
  document.getElementById('trfG').innerHTML = '<td>'+sug.length+' itens</td><td></td><td class="num">'+NF.format(tq)+'</td><td colspan="4"></td><td></td><td class="num">'+NF.format(te)+'</td><td></td>';
  document.getElementById('tbbG').addEventListener('change', function(e){
    const inp = e.target;
    if(!inp.matches || !inp.matches('input[data-x]')) return;
    const tr = inp.closest('tr'); const ix = parseInt(tr.getAttribute('data-ix'),10);
    const s = sug[ix]; const r = s.row;
    const ok = tr.querySelector('input[data-x=ok]').checked;
    const qtd = parseFloat(tr.querySelector('input[data-x=qtd]').value) || 0;
    const prev = getExec(r) || {};
    setExec(r, {ok:ok, qtd:qtd, rl:prev.rl, saldo:prev.saldo, quando:new Date().toISOString()});
    renderSug();
  });
  document.getElementById('tbbG').addEventListener('click', function(e){
    const btn = e.target;
    if(!btn.matches || !btn.matches('.exRl')) return;
    const tr = btn.closest('tr'); const ix = parseInt(tr.getAttribute('data-ix'),10);
    const s = sug[ix]; const r = s.row;
    const ex = getExec(r) || {ok:false,qtd:0};
    const saldo = Math.max(0, r.qtd - (ex.qtd||0));
    if(saldo<=0){ alert('Nada a realocar — a qtd executada cobre o planejado.'); return; }
    const nova = addDU(new Date(r.iso+'T12:00:00'), 1);
    setExec(r, {ok:ex.ok, qtd:ex.qtd, rl:isoD(nova), saldo:saldo});
    renderSug();
  });
}
renderSug();

// KPIs
function renderKpis(){
  const rs = visiveis(DATA.rows, 'chkFreteS');
  let tot=0, atr=0, sem1=0, prox4=0, vprod=0;
  const pvs = new Set();
  rs.forEach(function(r){
    const si = siOf(r);
    tot += r.vtot;
    vprod += vProd(r);
    if(si===0) atr += vPend(r);
    if(si===1) sem1 += vPend(r);
    if(si>=1 && si<=4) prox4 += vPend(r);
    pvs.add(String(r.pv)+'|'+r.empresa);
  });
  const lblAtr = 'Atrasado';
  document.getElementById('kpis').innerHTML =
    k('Carteira a entregar', FMT.format(tot), rs.length+' linhas · '+pvs.size+' PVs','') +
    k('Produzido (declarado)', FMT.format(vprod), 'coberto pela produção da semana','green') +
    k(lblAtr, FMT.format(atr), Math.round(atr/tot*100)+'% da carteira','red') +
    k('Semana atual ('+SEM[1]+')', FMT.format(sem1), 'pendente de produção','') +
    k('Próximas 4 semanas', FMT.format(prox4), SEM[1]+' → '+SEM[4],'');
  document.getElementById('fonte').textContent = 'planilha '+DATA.gerado;
  document.getElementById('badgeRows').textContent = rs.length+' itens';
  document.getElementById('badgePvs').textContent = pvs.size+' PVs';
  function k(l,v,d,cls){ return '<div class="kpi '+cls+'"><div class="lbl">'+l+'</div><div class="val">'+v+'</div><div class="det">'+d+'</div></div>'; }
}
