  // edição continua bloqueada para não-admin (viewerMode CSS + RLS admin-only)
  try{ const saved=JSON.parse(localStorage.getItem(DECL_KEY)||'null'); if(Array.isArray(saved)) return sanit(saved); }catch(e){}
  return sanit((DATA.progSemana && DATA.progSemana.declaracoes || []).map(function(d,i){return Object.assign({},d,{id:d.id||('PR-'+String(i+1).padStart(4,'0')),status:d.status||'Planejado'});}));
