function paLevar(rows){
  if(!Array.isArray(declDraft)){ try{ declDraft=declLoad(); }catch(e){ declDraft=[]; } }
  if(!Array.isArray(declDraft)) declDraft=[];
  const nomeDia=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
  let n=0;
  rows.forEach(function(s){
    if(!s) return;
    const d=new Date(s.iso+'T12:00:00');
    declDraft.push({dia:nomeDia[d.getDay()],data:s.iso,cod:s.cod,qtd:s.qtd,local:(window.UNID==='V')?'V':(s.local==='Vinhedo'?'V':'C'),pv:'',id:'PR-PA-'+Date.now()+'-'+(n++),obs:'sugestão programação automática'+(s.sem?' · '+s.sem:''),status:'Planejado'});
  });
  declSave(); progBuildFromDecls(); renderProg();
  alert(n+' alocação(ões) levada(s) para a Programação (aba Entregas por semana) — revise lá antes de considerar firme. Nada gravado no MaxiProd.');
}
