// ==================== VIEW FATURAMENTO (método Compass: NFs reais MaxiProd) ====================
function renderNf(liveOverride){
  const NF_MESN = ['','JANEIRO','FEVEREIRO','MARÇO','ABRIL','MAIO','JUNHO','JULHO','AGOSTO','SETEMBRO','OUTUBRO','NOVEMBRO','DEZEMBRO'];
  const NF_MESC = ['','Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
  const nf = liveOverride || DATA.nfFat;
  const hero = document.getElementById('nfHero');
  if(!nf){ hero.innerHTML = '<div class="card"><div class="note">Faturamento indisponível nesta geração (falha na busca MaxiProd).</div></div>'; return; }
  // ── Atualização ao vivo: busca os dados do backend Compass 2.1 (sync a cada 15 min) ──
  if(!liveOverride){
  fetch(FAT_URL).then(function(r){ return r.ok ? r.json() : null; }).then(function(live){
    if(!live || !live.ok || !live.nfs || !live.nfs.length) return;
    // Normaliza para o mesmo formato de DATA.nfFat e re-renderiza
    var brt = new Date(Date.now() - 3*3600*1000);
    var curY = brt.getUTCFullYear(), curM = brt.getUTCMonth() + 1;
    var lastDay = new Date(Date.UTC(curY + (curM === 12 ? 1 : 0), (curM % 12) + 1, 0)).getUTCDate();
    var mesIni = curY + '-' + ('0'+curM).slice(-2) + '-01';
    var mesFim = curY + '-' + ('0'+curM).slice(-2) + '-' + ('0'+lastDay).slice(-2);
    var daily = {}, monthly = {};
    live.nfs.forEach(function(n){
      var em = String(n.data || '');
      if(!em) return;
      var v = Number(n.valor || 0);
      if(mesIni <= em && em <= mesFim){ daily[em] = daily[em] || {q:0, v:0}; daily[em].q++; daily[em].v += v; }
      var mk = em.slice(0,7);
      monthly[mk] = monthly[mk] || {q:0, v:0}; monthly[mk].q++; monthly[mk].v += v;
    });
    function du(ini, fim){ var n=0, d=new Date(ini+'T00:00:00Z'); var e=new Date(fim+'T00:00:00Z'); while(d<=e){ if(d.getUTCDay()>0&&d.getUTCDay()<6) n++; d.setUTCDate(d.getUTCDate()+1);} return n; }
    var hojeIso=(new Date(Date.now()-3*3600*1000)).toISOString().slice(0,10);
    var daily_series = [], monthly_series = [];
    for(var dd=1; dd<=lastDay; dd++){ var k=curY+'-'+('0'+curM).slice(-2)+'-'+('0'+dd).slice(-2); if(k>hojeIso) continue; var o=daily[k]||{q:0,v:0}; daily_series.push({label:('0'+dd).slice(-2)+'/'+('0'+curM).slice(-2), qtd:o.q, valor:Math.round(o.v*100)/100}); }
    for(var mm2=1; mm2<=curM; mm2++){ var k2=curY+'-'+('0'+mm2).slice(-2); var o2=monthly[k2]||{q:0,v:0}; monthly_series.push({label:('0'+mm2).slice(-2)+'/'+curY, qtd:o2.q, valor:Math.round(o2.v*100)/100}); }
    var mesQtd=0, mesValor=0, anoQtd=0, anoValor=0;
    daily_series.forEach(function(s){ mesQtd+=s.qtd; mesValor+=s.valor; });
    monthly_series.forEach(function(s){ anoQtd+=s.qtd; anoValor+=s.valor; });
    var mesDu = du(mesIni, (new Date(Date.now() - 3*3600*1000)).toISOString().slice(0,10));
    var anoDu = du(curY+'-01-01', (new Date(Date.now() - 3*3600*1000)).toISOString().slice(0,10));
    // Média e mediana por DIA ÚTIL JÁ PASSADO (regra Dante 03/10): sem sáb/dom/feriados;
    // dias e meses futuros ficam FORA do cálculo.
    function feriados(ano){
      var f={};
      [[1,1],[4,21],[5,1],[9,7],[10,12],[11,2],[11,15],[12,25]].forEach(function(p){ f[ano+'-'+('0'+p[0]).slice(-2)+'-'+('0'+p[1]).slice(-2)]=1; });
      // Páscoa (Gauss)
      var a=ano%19, b=Math.floor(ano/100), c=ano%100;
      var d=Math.floor(b/4), e=b%4, g=Math.floor((b-Math.floor((b+8)/25)+1)/3);
      var h=(19*a+b-d-g+15)%30, i=Math.floor(c/4), k=c%4;
      var l=(32+2*e+2*i-h-k)%7, m=Math.floor((a+11*h+22*l)/451);
      var mp=Math.floor((h+l-7*m+114)/31), dp=((h+l-7*m+114)%31)+1;
      var pas=new Date(Date.UTC(ano, mp-1, dp));
      function iso(dt){ return dt.toISOString().slice(0,10); }
      f[iso(new Date(pas.getTime()-47*86400000))]=1; // Carnaval
      f[iso(new Date(pas.getTime()-2*86400000))]=1;  // Sexta-feira Santa
      f[iso(new Date(pas.getTime()+60*86400000))]=1; // Corpus Christi
      return f;
    }
    var FER = feriados(curY);
    function mediana(vals){
      if(!vals.length) return 0;
      var s2=vals.slice().sort(function(a,b){return a-b;});
      var n=s2.length;
      return n%2 ? s2[(n-1)/2] : (s2[n/2-1]+s2[n/2])/2;
    }
    var mesDuVals=[];
    for(var dd2=1; dd2<=lastDay; dd2++){
      var k3=curY+'-'+('0'+curM).slice(-2)+'-'+('0'+dd2).slice(-2);
      if(k3>hojeIso) continue; // futuro não entra
      var wd=new Date(Date.UTC(curY, curM-1, dd2)).getUTCDay();
      if(wd>0 && wd<6 && !FER[k3]) mesDuVals.push((daily[k3]||{v:0}).v);
    }
    var anoMesVals=monthly_series.filter(function(m){ return +m.label.slice(0,2)<=curM; }).map(function(m){return m.valor;});
    var anoDuCount=0; // dias úteis já passados no ANO (sem sáb/dom/feriados) — 1º jan até hoje
    for(var mi=1; mi<=curM; mi++){
      var dim=new Date(Date.UTC(curY, mi, 0)).getUTCDate();
      for(var di=1; di<=dim; di++){
        var k4=curY+'-'+('0'+mi).slice(-2)+'-'+('0'+di).slice(-2);
        if(k4>hojeIso) break;
        var wd=new Date(Date.UTC(curY, mi-1, di)).getUTCDay();
        if(wd>0 && wd<6 && !FER[k4]) anoDuCount++;
      }
    }
    var liveNfs = live.nfs.slice().sort(function(a,b){ return String(b.data).localeCompare(String(a.data)); });
    var liveData = {
      mesLabel: ('0'+curM).slice(-2)+'/'+curY, ano: curY, hoje: hojeIso,
      daily: daily_series, monthly: monthly_series,
      mesQtd: mesQtd, mesValor: Math.round(mesValor*100)/100, anoQtd: anoQtd, anoValor: Math.round(anoValor*100)/100,
      mesDiasUteis: mesDuVals.length, anoDiasUteis: mesDuVals.length ? anoDuCount : anoDu,
      mediaDiaUtilMes: mesDuVals.length ? Math.round(mesValor/mesDuVals.length) : 0,
      mediaDiaUtilAno: anoDuCount ? Math.round(anoValor/anoDuCount) : 0,
      mediaDuMes: mesDuVals.length ? Math.round(mesDuVals.reduce(function(a,b){return a+b;},0)/mesDuVals.length) : 0,
      mediaDuAno: Math.round(anoValor/curM),
      medianaMes: Math.round(mediana(mesDuVals.filter(function(v){return v>0;}))),  // mediana diária: só dias úteis que FATURARAM
      medianaAno: Math.round(mediana(anoMesVals)),
      nfs: liveNfs
    };
    window._nfLive = liveData;
    if(window._nfRenderAll) window._nfRenderAll(liveData);
  }).catch(function(){ /* fallback: mantém dados estáticos */ });
  }
  const F0 = new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
  const F2 = new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:2});
  const NUM = new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2});
  const mm = parseInt(nf.mesLabel.slice(0,2),10);

  // ---------- HERO ----------
  hero.innerHTML =
    '<div class="nfHero">'+
      '<div class="heroMain">'+
        '<div class="heroTtl">FATURAMENTO — '+(NF_MESN[mm]||'')+'/'+nf.ano+'</div>'+
        '<div class="heroBig">'+F0.format(nf.mesValor)+'</div>'+
        '<div class="heroSub">'+nf.mesQtd+' NFs emitidas · média '+F0.format(nf.mediaDiaUtilMes)+'/dia útil ('+nf.mesDiasUteis+' dias úteis)</div>'+
        '<div class="heroSpark" id="nfSpark"></div>'+
      '</div>'+
      '<div class="heroYear">'+
        '<div class="yLbl">Acumulado '+nf.ano+'</div>'+
        '<div class="yBig">'+F0.format(nf.anoValor)+'</div>'+
        '<div class="ySub">'+nf.anoQtd+' NFs · média '+F0.format(nf.mediaDiaUtilAno)+'/dia útil · '+nf.anoDiasUteis+' dias úteis</div>'+
      '</div>'+
    '</div>';
  const sp = echarts.init(document.getElementById('nfSpark'));
  if(window._nfCharts){ window._nfCharts.forEach(function(c){ try{ c.dispose(); }catch(e){} }); }
  sp.setOption({grid:{left:2,right:2,top:6,bottom:6},
    tooltip:{trigger:'axis',formatter:function(ps){var d=nf.daily[ps[0].dataIndex];return d.label+'<br/>'+F0.format(d.valor)+' · '+d.qtd+' NFs';}},
    xAxis:{type:'category',show:false,boundaryGap:false,data:nf.daily.map(function(d){return d.label;})},
    yAxis:{type:'value',show:false},
    series:[{type:'line',smooth:true,symbol:'none',data:nf.daily.map(function(d){return d.valor;}),
             lineStyle:{color:'#93c5fd',width:2},areaStyle:{color:'rgba(147,197,253,.20)'}}]});

  // ---------- CHARTS ----------
  document.getElementById('nfMesLbl').textContent = nf.mesLabel;
  document.getElementById('nfAnoLbl').textContent = nf.ano;
  const nfAnoGraf=document.getElementById('nfAnoGraf'); if(nfAnoGraf) nfAnoGraf.textContent=nf.ano;
  const nfPeriodo = document.getElementById('nfHistPeriodo'); if(nfPeriodo) nfPeriodo.textContent = 'Ano de '+nf.ano+' (Jan–Dez)';
  document.getElementById('nfTblAno').textContent = nf.ano;
  const c1 = echarts.init(document.getElementById('chNfDia'));
  // padrão Compass (projeto C): mês inteiro compacto, barras finas, média tracejada amber
  var mmCur = parseInt(nf.mesLabel.slice(0,2),10), yyCur = nf.ano;
  var lastDayCur = new Date(Date.UTC(yyCur, mmCur, 0)).getUTCDate();
  var byDay = {}; nf.daily.forEach(function(d){ byDay[d.label.slice(0,2)] = d; });
  var dailyFull = [];
  for(var dd=1; dd<=lastDayCur; dd++){
    var lbl = ('0'+dd).slice(-2)+'/'+('0'+mmCur).slice(-2);
    var o = byDay[('0'+dd).slice(-2)];
    dailyFull.push(o ? {label:lbl, dia:String(dd), qtd:o.qtd, valor:o.valor} : {label:lbl, dia:String(dd), qtd:0, valor:0});
  }
  var mMes = nf.mediaDuMes!==undefined?nf.mediaDuMes:nf.mediaDiaUtilMes;
  var fmtY = function(v){ if(v>=1e6) return 'R$ '+(v/1e6).toFixed(1).replace('.',',')+'mi'; if(v>=1e3) return 'R$ '+Math.round(v/1e3)+'mil'; return 'R$ '+v; };
  c1.setOption({grid:{left:12,right:10,top:20,bottom:24,containLabel:true},
    tooltip:{trigger:'axis',backgroundColor:'rgba(15,23,42,.96)',borderColor:'rgba(165,180,252,.38)',textStyle:{color:'#fff',fontSize:13},formatter:function(ps){var d=dailyFull[ps[0].dataIndex];return d.label+'<br/>'+F0.format(d.valor)+' · '+d.qtd+' NFs';}},
    xAxis:{type:'category',data:dailyFull.map(function(d){return d.dia;}),axisLabel:{fontSize:11,color:'rgba(219,234,254,.88)',interval:2,showMaxLabel:true},axisTick:{show:false},axisLine:{lineStyle:{color:'rgba(255,255,255,.24)'}}},
    yAxis:{type:'value',axisLabel:{fontSize:11,color:'rgba(219,234,254,.88)',formatter:fmtY,margin:8},axisLine:{show:false},axisTick:{show:false},splitLine:{lineStyle:{color:'rgba(255,255,255,.12)'}}},
    series:[{name:'Faturamento',type:'bar',data:dailyFull.map(function(d){return d.valor;}),barCategoryGap:'25%',
             itemStyle:{color:'#3b82f6',borderRadius:[4,4,0,0]},
             markLine:{silent:true,symbol:'none',data:[{yAxis:mMes}],
               lineStyle:{color:'#f59e0b',type:'dashed',width:1.5},
               label:{show:true,position:'insideMiddleTop',formatter:'Média: '+F0.format(Math.round(mMes))+'/dia útil',color:'#fbbf24',fontSize:11,fontWeight:'bold'}}}]});
  // Duas leituras mensais conforme o Compass C, derivadas da mesma série fiscal existente.
  // O preenchimento Jan-Dez é somente visual; períodos ainda sem NFs ficam em zero.
  var nfMonthShort=['','Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  var nfYear=Number(nf.ano)||new Date().getFullYear();
  var nfMonthlyRaw=Array.isArray(nf.monthly)?nf.monthly:[];
  var nfMonthlyFull=[];
  for(var monthIdx=1;monthIdx<=12;monthIdx++){
    var monthKey=('0'+monthIdx).slice(-2);
    var existingMonth=nfMonthlyRaw.find(function(m){return String(m.label||'').slice(0,2)===monthKey;});
    nfMonthlyFull.push({label:nfMonthShort[monthIdx]+'/'+String(nfYear).slice(-2),
      qtd:existingMonth?(Number(existingMonth.qtd)||0):0,
      valor:existingMonth?(Number(existingMonth.valor)||0):0});
  }
  var histValueTotal=nfMonthlyFull.reduce(function(total,m){return total+m.valor;},0);
  var valuePeak=Math.max.apply(null,nfMonthlyFull.map(function(m){return m.valor;}));
  var valueAxisMax=Math.max(6000000,Math.ceil(valuePeak/1500000)*1500000);
  var fmtHistMoney=function(v){
    if(v>=1000000){var mm=v/1000000;return 'R$ '+(Number.isInteger(mm)?mm.toFixed(0):mm.toFixed(1).replace('.',','))+' mi';}
    if(v>=1000)return 'R$ '+Math.round(v/1000)+' mil';
    return 'R$ '+Math.round(v);
  };
  var fmtHistTotal=function(v){
    if(v>=1000000)return 'R$ '+(v/1000000).toFixed(1).replace('.',',')+' mi';
    if(v>=1000)return 'R$ '+Math.round(v/1000)+' mil';
    return F0.format(v);
  };
  var vTotalEl=document.getElementById('nfTotAno');if(vTotalEl)vTotalEl.textContent=F0.format(histValueTotal);
  // Substituição solicitada: faturamento diário neste painel, sem gráfico mensal de contagem de NFs.
  const c2 = echarts.init(document.getElementById('chNfMes'));
  var mAno = nf.mediaDuAno!==undefined?nf.mediaDuAno:nf.mediaDiaUtilAno;
  c2.setOption({grid:{left:12,right:10,top:20,bottom:24,containLabel:true},
    tooltip:{trigger:'axis',backgroundColor:'rgba(15,23,42,.96)',borderColor:'rgba(165,180,252,.38)',
      textStyle:{color:'#fff',fontSize:13},
      formatter:function(ps){var m=nfMonthlyFull[ps[0].dataIndex];return m.label+'<br/>'+F0.format(m.valor)+' · '+NF.format(m.qtd)+' NFs';}},
    xAxis:{type:'category',data:nfMonthlyFull.map(function(m){return m.label;}),
      axisLabel:{fontSize:11,color:'rgba(255,255,255,.84)',hideOverlap:true},axisTick:{show:false},
      axisLine:{lineStyle:{color:'rgba(255,255,255,.24)'}}},
    yAxis:{type:'value',min:0,max:valueAxisMax,splitNumber:4,
      axisLabel:{fontSize:11,color:'rgba(255,255,255,.84)',formatter:fmtHistMoney,margin:8},
      axisLine:{show:false},axisTick:{show:false},splitLine:{lineStyle:{color:'rgba(255,255,255,.12)'}}},
    series:[{name:'Valor',type:'bar',data:nfMonthlyFull.map(function(m){return m.valor;}),barCategoryGap:'25%',
      itemStyle:{color:'#3b82f6',borderRadius:[4,4,0,0]},
      label:{show:true,position:'top',fontSize:10,fontWeight:600,color:'#dbeafe',
        formatter:function(p){return p.value>0?(p.value/1e6).toFixed(1).replace('.',',')+'M':'';}}}]});
  var elT1=document.getElementById('nfTotMes'); if(elT1) elT1.textContent=F0.format(nf.mesValor);
  var elM1=document.getElementById('nfMedMes'); if(elM1) elM1.textContent=F0.format(mMes);
  var elT2=document.getElementById('nfTotAno'); if(elT2) elT2.textContent=fmtHistTotal(histValueTotal);
  window._nfCharts = [sp, c1, c2];
  var nfFoot = document.getElementById('nfFormula');
  if(nfFoot){
    var mMedia = nf.mediaDuMes!==undefined?nf.mediaDuMes:nf.mediaDiaUtilMes;
    var mMed = nf.medianaMes!==undefined?nf.medianaMes:0;
    var aMedia = nf.mediaDuAno!==undefined?nf.mediaDuAno:nf.mediaDiaUtilAno;
    var aMed = nf.medianaAno!==undefined?nf.medianaAno:0;
    nfFoot.innerHTML = '<b>Como calculamos:</b> média/dia útil = soma do valor faturado ÷ dias úteis JÁ PASSADOS do período (sem sábados, domingos e feriados; dias e meses futuros não entram) — mês '+F0.format(mMedia)+' · ano '+F0.format(aMedia)+'. Mediana = valor central entre os períodos já passados ordenados — mês '+F0.format(mMed)+' · ano '+F0.format(aMed)+'.';
  }

  // ---------- TABELA (filtros + ordenação + paginação + drill-down) ----------
  const state = window._nfState || (window._nfState = {q:'',mes:'',emp:'',sortKey:'data',sortDir:'desc',page:0});
  const PER = 50;
  if(!window._nfSelInit){
    var mopts = '<option value="">Todos os meses</option>';
    for(var m=1;m<=12;m++){ var k=('0'+m).slice(-2); mopts += '<option value="'+k+'">'+NF_MESC[m]+'</option>'; }
    document.getElementById('nfMesSel').innerHTML = mopts;
    var emps = [];
    nf.nfs.forEach(function(n){ if(n.emp && emps.indexOf(n.emp)<0) emps.push(n.emp); });
    emps.sort();
    document.getElementById('nfEmpSel').innerHTML = '<option value="">Todas as empresas</option>'+emps.map(function(e){return '<option value="'+escH(e)+'">'+escH(e)+'</option>';}).join('');
    window._nfSelInit = true;
  }
  function nfMatch(n){
    if(state.mes && n.data.slice(5,7)!==state.mes) return false;
    if(state.emp && n.emp!==state.emp) return false;
    if(state.q){
      var hay = (n.nf+' '+n.cliente+' '+n.cidade+' '+n.uf+' '+n.op+' '+n.emp+' '+n.itens.map(function(it){return it.cod+' '+it.desc+' '+(it.pv||'');}).join(' ')).toLowerCase();
      if(hay.indexOf(state.q)<0) return false;
    }
    return true;
  }
  function nfCmp(a,b){
    var va,vb,k=state.sortKey;
    if(k==='valor'){ va=a.valor; vb=b.valor; }
    else if(k==='nf'){ va=parseInt(a.nf,10)||0; vb=parseInt(b.nf,10)||0; }
    else if(k==='destino'){ va=(a.cidade+a.uf).toLowerCase(); vb=(b.cidade+b.uf).toLowerCase(); }
    else if(k==='cliente'||k==='emp'||k==='op'){ va=(a[k]||'').toLowerCase(); vb=(b[k]||'').toLowerCase(); }
    else { va=a[k]||''; vb=b[k]||''; }
    if(va<vb) return state.sortDir==='asc'?-1:1;
    if(va>vb) return state.sortDir==='asc'?1:-1;
    return 0;
  }
  function nfRenderTable(){
    var filt = nf.nfs.filter(nfMatch);
    filt.sort(nfCmp);
    var totV = 0; for(var j=0;j<filt.length;j++) totV += filt[j].valor;
    document.getElementById('nfTblCount').innerHTML = '<b>'+filt.length+'</b> NFs · <b>'+F0.format(totV)+'</b>';
    var pages = Math.max(1, Math.ceil(filt.length/PER));
    if(state.page>=pages) state.page = pages-1;
    if(state.page<0) state.page = 0;
    var slice = filt.slice(state.page*PER, (state.page+1)*PER);
    document.getElementById('nfTb').innerHTML = slice.map(function(n){
      var dt = n.data.slice(8,10)+'/'+n.data.slice(5,7)+'/'+n.data.slice(0,4);
      var destino = (n.cidade||'—')+(n.uf?'/'+n.uf:'');
      var itens = n.itens.map(function(it){
        return '<tr><td>'+escH(it.cod)+'</td><td>'+escH(it.desc)+'</td><td>'+(it.pv?'<b class="pvtag">'+escH(it.pv)+'</b>':'—')+'</td><td class="r">'+NUM.format(it.qtd)+'</td><td class="r">'+F2.format(it.valor)+'</td></tr>';
      }).join('') || '<tr><td colspan="5">Sem itens.</td></tr>';
      var det = '<tr class="nfdet" style="display:none"><td colspan="8"><table class="mini"><thead><tr><th>Código</th><th>Descrição</th><th>PV</th><th class="r">Qtd</th><th class="r">Valor</th></tr></thead><tbody>'+itens+'</tbody></table></td></tr>';
      return '<tr class="nfrow"><td class="exp">▸</td><td><b>'+escH(n.nf)+'</b></td><td>'+dt+'</td><td>'+escH(n.emp)+'</td>'+
        '<td class="nfcli" title="'+escH(n.cliente)+'">'+escH(n.cliente||'—')+'</td>'+
        '<td>'+escH(destino)+'</td>'+
        '<td class="nfop" title="'+escH(n.op)+'">'+escH(n.op||'—')+'</td>'+
        '<td class="nfval">'+F2.format(n.valor)+'</td></tr>'+det;
    }).join('') || '<tr><td colspan="8" style="text-align:center;color:var(--mut);padding:16px">Nenhuma NF encontrada.</td></tr>';
    document.getElementById('nfPager').innerHTML = pages>1 ?
      '<button data-pg="prev"'+(state.page===0?' disabled':'')+'>‹ Anterior</button>'+
      '<span>Página '+(state.page+1)+' de '+pages+'</span>'+
      '<button data-pg="next"'+(state.page>=pages-1?' disabled':'')+'>Próxima ›</button>' : '';
    document.querySelectorAll('#tbNf th[data-sort]').forEach(function(th){
      var k = th.getAttribute('data-sort');
      var base = th.getAttribute('data-lbl');
      if(base===null){ base = th.textContent; th.setAttribute('data-lbl', base); }
      th.innerHTML = base + (k===state.sortKey ? ' <span class="arw">'+(state.sortDir==='asc'?'▲':'▼')+'</span>' : '');
    });
  }
  window._nfRenderTable = nfRenderTable;
  if(!window._nfTblWired){
    document.getElementById('nfSearch').addEventListener('input', function(e){ state.q = e.target.value.trim().toLowerCase(); state.page=0; nfRenderTable(); });
    document.getElementById('nfMesSel').addEventListener('change', function(e){ state.mes = e.target.value; state.page=0; nfRenderTable(); });
    document.getElementById('nfEmpSel').addEventListener('change', function(e){ state.emp = e.target.value; state.page=0; nfRenderTable(); });
    document.querySelectorAll('#tbNf th[data-sort]').forEach(function(th){
      th.addEventListener('click', function(){
        var k = th.getAttribute('data-sort');
        if(state.sortKey===k){ state.sortDir = state.sortDir==='asc'?'desc':'asc'; }
        else { state.sortKey = k; state.sortDir = (k==='valor'||k==='data'||k==='nf') ? 'desc' : 'asc'; }
        state.page = 0; nfRenderTable();
      });
    });
    document.getElementById('tbNf').addEventListener('click', function(e){
      var tr = e.target.closest('tr.nfrow'); if(!tr) return;
      var det = tr.nextElementSibling;
      if(det && det.classList.contains('nfdet')){
        var show = det.style.display==='none';
        det.style.display = show ? '' : 'none';
        tr.classList.toggle('open', show);
        var ex = tr.querySelector('td.exp'); if(ex) ex.textContent = show ? '▾' : '▸';
      }
    });
    document.getElementById('nfPager').addEventListener('click', function(e){
      var b = e.target.closest('button[data-pg]'); if(!b) return;
      state.page += (b.getAttribute('data-pg')==='prev' ? -1 : 1);
      nfRenderTable();
      var w = document.querySelector('#viewNf .tblwrap'); if(w) w.scrollTop = 0;
    });
    window._nfTblWired = true;
  }
  nfRenderTable();
  window._nfInit = true;
}
// Re-render completo da aba Faturamento com dados ao vivo (chamado pelo fetch do backend)
window._nfRenderAll = function(liveData){
  window._nfSelInit = false; // reconstrói os selects de empresa; listeners estáticos NÃO são rearmados
  renderNf(liveData);
};

// ==================== VIEW CARTEIRA A FATURAR ====================
const MES_N = {'01':'Janeiro','02':'Fevereiro','03':'Março','04':'Abril','05':'Maio','06':'Junho','07':'Julho','08':'Agosto','09':'Setembro','10':'Outubro','11':'Novembro','12':'Dezembro'};
function mesLabel(m){ return m==='ATRASADO' ? 'Atrasado' : (MES_N[m.slice(5,7)]||'')+' / '+m.slice(0,4); }
function dtBR(iso){ return iso ? iso.slice(8,10)+'/'+iso.slice(5,7) : '—'; }
function qtdPendF(r){ return r.prod ? Math.max(0, r.qtd - r.prod.qtd) : r.qtd; }
function vPendF(r){ return r.vtot * (r.qtd ? qtdPendF(r)/r.qtd : 0); }
function vProdF(r){ return r.vtot - vPendF(r); }

function renderFat(){
  const rs = DATA.rows;
  // v0.0.314 (regra Dante 11/10): aba Produtos a Faturar mostra LÍQUIDO —
  // qtd/valor = saldo a faturar − produção declarada − saldo SMKT (conta fecha).
  // v0.0.318: checkbox de fretes fica SÓ no card "Por produto" (renderFatProds).
  const TOTB = rs.reduce((a,r)=>a+r.vtot,0);
  const TOT = rs.reduce((a,r)=>a+vPend(r),0);
  const ATR = rs.filter(r=>siOf(r)===0).reduce((a,r)=>a+vPend(r),0);
  const VPROD = TOTB - TOT;
  const PVS = new Set(rs.filter(r=>qtdPend(r)>0).map(r=>r.pv+'|'+r.empresa)).size;
  document.getElementById('fKpis').innerHTML =
    '<div class="kpi"><div class="v">'+FMT.format(TOT)+'</div><div class="l">Carteira líquida a faturar ('+rs.length+' itens)</div></div>'+
    '<div class="kpi"><div class="v">'+PVS+'</div><div class="l">PVs com saldo a faturar</div></div>'+
    '<div class="kpi red"><div class="v">'+FMT.format(ATR)+'</div><div class="l">Atrasado ('+(TOT>0?(100*ATR/TOT).toFixed(0):0)+'% da carteira)</div></div>'+
    '<div class="kpi green"><div class="v">'+FMT.format(VPROD)+'</div><div class="l">Produzido + SMKT (já descontado)</div></div>';

  // por empresa
  const emp = {};
  rs.forEach(function(r){
    const o = emp[r.empresa] = emp[r.empresa] || {vt:0,qtd:0,atr:0,pvs:new Set()};
    o.vt += vPend(r); o.qtd += qtdPend(r); if(siOf(r)===0) o.atr += vPend(r); o.pvs.add(r.pv);
  });
  document.getElementById('fEmp').innerHTML = Object.entries(emp).sort((a,b)=>b[1].vt-a[1].vt).filter(e=>e[1].qtd>0||e[1].vt>0).map(function(e){
    const [nome,o] = e;
    return '<div class="card" style="padding:12px 14px"><div style="display:flex;justify-content:space-between;align-items:baseline;font-size:13.5px"><span>'+nome+'</span><b>'+FMT.format(o.vt)+'</b></div>'+
      '<div class="bar"><i style="width:'+(o.vt>0?(100*o.atr/o.vt).toFixed(0):0)+'%"></i></div>'+
      '<small style="color:var(--mut)">'+o.pvs.size+' PVs · '+NF.format(o.qtd)+' un · atrasado '+FMT.format(o.atr)+' ('+(o.vt>0?(100*o.atr/o.vt).toFixed(0):0)+'%)</small></div>';
  }).join('');

  // por mês
  const mes = {};
  rs.forEach(function(r){
    const k = siOf(r)===0 ? 'ATRASADO' : r.iso.slice(0,7);
    const o = mes[k] = mes[k] || {vt:0,qtd:0,pvs:new Set(),n:0};
    o.vt += vPend(r); o.qtd += qtdPend(r); o.n++; o.pvs.add(r.pv+'|'+r.empresa);
  });
  document.getElementById('fMes').innerHTML = Object.entries(mes).sort((a,b)=>a[0].localeCompare(b[0])).filter(m=>m[1].qtd>0||m[1].vt>0).map(function(m){
    const [k,o] = m;
    return '<tr><td>'+mesLabel(k)+'</td><td class="num">'+NF.format(o.qtd)+'</td><td class="num"><b>'+FMT.format(o.vt)+'</b></td><td class="num">'+o.pvs.size+'</td><td class="num">'+o.n+'</td></tr>';
  }).join('');

  renderFatProds(); renderFatAll();
}

// por produto com drill PV
let fatQ = '';
let fatSemPool = ''; // pool de semanas já populado no select (evita recriar e perder seleção)
function renderFatProds(){
  const q = fatQ.toUpperCase();
  // v0.0.318 (regra Dante): o toggle de fretes é exclusivo deste card — padrão SEM fretes
  let rowsF = (function(){ try{ return visiveis(DATA.rows,'chkFreteF'); }catch(e){ return DATA.rows; } })();
  // v0.0.404 (Dante 14/10): filtros do card "Por produto" — só atrasados + semanas selecionadas
  const chkAtr=document.getElementById('chkAtrasF');
  const selSem=document.getElementById('fSemSel');
  if(selSem&&!fatSemPool){
    const semanas=[]; rowsF.forEach(function(r){ const si=siOf(r); const lab=SEM[si]||''; if(lab&&semanas.indexOf(lab)<0)semanas.push(lab); });
    semanas.sort();
    fatSemPool=semanas.join('|');
    semanas.forEach(function(s){ const o=document.createElement('option'); o.value=s; o.textContent=s; selSem.appendChild(o); });
  }
  const semSel=selSem?Array.prototype.filter.call(selSem.options,function(o){return o.selected;}).map(function(o){return o.value;}):[];
  if(chkAtr&&chkAtr.checked) rowsF=rowsF.filter(function(r){ return siOf(r)===0; });
  if(semSel.length) rowsF=rowsF.filter(function(r){ return semSel.indexOf(SEM[siOf(r)]||'')>=0; });
  // v0.0.419 (Dante 16/10): filtros de desconto do card "Por produto" — 2 checkboxes independentes
  // bruto (nenhum marcado) = todas que faltam faturar (número da equipe);
  // − SMKT desconta entradas do supermercado; − declarada desconta produção declarada;
  // ambos = líquido (comportamento padrão anterior).
  const chkSm=document.getElementById('chkSmktF'), chkDe=document.getElementById('chkDeclF');
  const desSm = chkSm ? chkSm.checked : true;   // padrão: desconta (líquido)
  const desDe = chkDe ? chkDe.checked : true;   // padrão: desconta (líquido)
  function qtdPendFiltro(r){
    let base = r.qtd;
    if(desDe && r.prod) base = Math.max(0, base - r.prod.qtd);
    if(desSm){
      let extra = smktExtraForRow(r);
      base = Math.max(0, base - extra);
    }
    return base;
  }
  function vPendFiltro(r){ return r.vtot * (r.qtd ? qtdPendFiltro(r)/r.qtd : 0); }
  // v0.0.421 (Dante 17/10): ET0006 (código antigo da esteira Berenice) SOMA na linha 404-0001;
  // Matilde 404-0002 segue separada (outro projeto).
  const COD_ALIAS = {'ET0006':'404-0001'};
  function codEfetivo(r){ return COD_ALIAS[r.codigo] || r.codigo; }
  const map = {};
  rowsF.forEach(function(r){
    // v0.0.316: linha 100% produzida/SMKT ENTRA (soma 0) — aparece riscada no drill-down
    const codE = codEfetivo(r);
    const o = map[codE] = map[codE] || {desc:r.desc,frete:r.frete,qtd:0,vt:0,atr:0,pvs:{},cods:{}};
    if(!o.cods[r.codigo]) o.cods[r.codigo]=0;
    o.cods[r.codigo] += qtdPendFiltro(r);
    o.qtd += qtdPendFiltro(r); o.vt += vPendFiltro(r); if(siOf(r)===0) o.atr += vPendFiltro(r);
    const k = r.pv+'|'+r.empresa;
    o.pvs[k] = o.pvs[k] || {pv:r.pv,cli:r.cliente,emp:r.empresa,qtd:0,vt:0,data:r.iso,atr:siOf(r)===0,prod:r.prod,local:r.local,qtdBr:r.qtd,vtBr:r.vtot,cod:r.codigo};
    o.pvs[k].qtd += qtdPendFiltro(r); o.pvs[k].vt += vPendFiltro(r);
  });
  const arr = Object.entries(map).filter(function(e){ return e[1].qtd>0 || e[1].vt>0; }).sort((a,b)=>b[1].vt-a[1].vt);  let html = arr.map(function(p,ix){
    const [cod,o] = p;
    const multiCod = Object.keys(o.cods).length>1;
    const pvRows = Object.values(o.pvs).sort((a,b)=>a.pv-b.pv).map(function(v){
      const trn = trDe(v.local, v.cli, v.data);
      const vin = v.local==='Vinhedo' ? ' style="background:#FFF9C4"' : '';
      const zerada = v.qtd<=0;
      const qtdCell = zerada
        ? '<span class="note" style="color:var(--mut)">'+NF.format(v.qtdBr)+' ✓</span>'
        : NF.format(v.qtd);
      const vtCell = zerada
        ? '<span class="note" style="color:var(--mut)">'+FMT.format(v.vtBr)+' ✓</span>'
        : FMT.format(v.vt);
      const pvCod = multiCod && v.cod && v.cod!==cod ? ' <span class="note">('+v.cod+')</span>' : '';
      return '<tr'+vin+'><td><b>'+v.pv+'</b>'+pvCod+'</td><td>'+v.cli+'</td><td>'+v.emp+'</td><td>'+dtBR(v.data)+(v.atr?' <span class="tagF">ATRASADO</span>':'')+'</td><td class="num">'+qtdCell+'</td><td class="num">'+vtCell+'</td><td>'+v.local+'</td><td>'+(trn?trn.cheg:'—')+'</td>'+(v.prod?'<td><span class="tagP">PRODUZIDO '+dtBR(v.prod.dmax||v.prod.dd||'')+'</span></td>':'<td></td>')+'</tr>';
    }).join('');
    // v0.0.315: PVs 100% produzidos/SMKT NÃO somem do drill-down — aparecem riscados (referência)
    const zeradas = Object.values(o.pvs).filter(function(v){ return v.qtd<=0; }).length;
    const multiCodAgg = Object.keys(o.cods).length>1;
    const codsTxt = multiCodAgg ? Object.entries(o.cods).filter(function(e){ return e[1]>0; }).map(function(e){ return e[0]+' '+NF.format(e[1]); }).join(' + ') : '';
    const det = '<tr class="detrow" data-det="'+ix+'" style="display:none"><td colspan="5"><table class="mini"><tr><th>PV</th><th>Cliente</th><th>Empresa</th><th>Entrega</th><th>Qtd</th><th>Valor</th><th>Local</th><th>Chegada prevista</th><th>Produção</th></tr>'+pvRows+(zeradas?'<tr><td colspan="9" class="note">✓ '+zeradas+' PV(s) já 100% produzido/SMKT — aparece(m) riscado(s), não entra(m) na conta líquida.</td></tr>':'')+'</table></td></tr>';
    return '<tr class="prow" data-ix="'+ix+'"><td><div class="cod">'+cod+(o.frete?' <span class="tagF">FRETE</span>':'')+'</div><div class="dsc">'+o.desc.slice(0,52)+(codsTxt?' <span class="note">('+codsTxt+')</span>':'')+'</div></td>'+
      '<td class="num">'+NF.format(o.qtd)+'</td><td class="num"><b>'+FMT.format(o.vt)+'</b></td>'+
      '<td class="num">'+Object.keys(o.pvs).length+'</td><td class="num '+(o.atr?'neg':'')+'">'+(o.atr?FMT.format(o.atr):'—')+'</td></tr>'+det;
  }).join('');
  // v0.0.405 (Dante 15/10): linha de TOTAL ao final da lista, conforme a seleção/filtros ativos
  if(arr.length){
    const T={qtd:0,vt:0,atr:0,pvs:new Set()};
    arr.forEach(function(p){ T.qtd+=p[1].qtd; T.vt+=p[1].vt; T.atr+=p[1].atr; Object.keys(p[1].pvs).forEach(function(k){T.pvs.add(k);}); });
    html+='<tr style="position:sticky;bottom:0;background:var(--bg,#F1F5F9);font-weight:700;border-top:2px solid var(--mut,#94A3B8)"><td>TOTAL — '+arr.length+' produto(s) · '+T.pvs.size+' PV(s)</td>'+
      '<td class="num">'+NF.format(T.qtd)+'</td><td class="num">'+FMT.format(T.vt)+'</td>'+
      '<td class="num">'+T.pvs.size+'</td><td class="num">'+(T.atr?FMT.format(T.atr):'—')+'</td></tr>';
  }
  document.getElementById('fProd').innerHTML = html || '<tr><td colspan="5">Nada encontrado.</td></tr>';
}
