// ==================== v0.0.202: AUTO-DETECÇÃO DE VERSÃO VELHA (cache CDN) ====================
// Sintoma do incidente 04/10: Dante com versão antiga em cache — botão Programar sem modal.
// O gerador estampa o build (b20261006224828); a página aberta confere a produção a cada 5 min e
// avisa (barra no topo) quando a versão publicada é mais nova. Recarrega com Ctrl+F5.
(function(){
  const BUILD=document.body.getAttribute('data-build')||'';
  function checkVer(){
    try{
      fetch(location.pathname+'?cb='+Date.now(), {cache:'no-store'}).then(function(r){ return r.text(); }).then(function(t){
        // o build REAL sempre aparece primeiro no atributo body data-build="..." (o código JS vem depois)
        const m = t.match(/data-build="([^"]+)"/);
        if(m && m[1] && m[1] !== BUILD){
          let bar = document.getElementById('verBar');
          if(!bar){
            bar = document.createElement('div');
            bar.id='verBar';
            bar.style.cssText='position:fixed;top:0;left:0;right:0;z-index:999;background:#b45309;color:#fff;font-size:13px;font-weight:700;padding:8px 16px;text-align:center;cursor:pointer';
            bar.textContent='⬆ Nova versão disponível — clique aqui para atualizar o painel';
            bar.addEventListener('click', function(){ location.reload(true); });
            document.body.appendChild(bar);
          }
          bar.style.display='block';
        }
      });
    }catch(e){}
  }
  checkVer();
  setInterval(checkVer, 300000);
})();


