  if(d&&Array.isArray(d.linhas)&&d.linhas.length){ hhLinhasCfg=d.linhas; hhProdCfg=Array.isArray(d.produtos)?d.produtos:[]; }
  else { hhLinhasCfg=[]; hhProdCfg=[]; }
  hhCfgData=iso;
