function hhMonV2ActualCut(c,iso,now){const d=now||new Date(),today=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return String(iso)>=today?1440:hhScheduleEnd(c);}
