// ===== v0.0.436 — binding GLOBAL dos botões de tela do monitor =====
// A view HH pode não casar com "#viewHH [data-hh-view]" (mesma causa raiz do CSS v0.0.431-433);
// sem este binding, os cliques em Monitor geral/Individual/Gestão não fazem nada.
(function(){
 function hh436BindViews(){
  document.querySelectorAll('[data-hh-view]').forEach(function(b){
   if(b._hh436Bound)return;b._hh436Bound=true;
   b.addEventListener('click',function(e){
    e.stopPropagation();
    var key=b.getAttribute('data-hh-view');
    try{hhSetMonitorScreen(key);}catch(e1){}
    try{document.querySelectorAll('[data-hh-view]').forEach(function(x){var on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on?'true':'false');});}catch(e4){}
    try{var pick=document.querySelector('.hhIndividualSelect');if(pick)pick.style.display=(key==='individual'?'flex':'none');}catch(e2){}
    try{hhRender();}catch(e3){}
    if(key==='gestao'&&window.echarts&&typeof hhChart!=='undefined'&&hhChart)setTimeout(function(){hhChart.resize();},80);
   });
  });
 }
 hh436BindViews();
 setTimeout(hh436BindViews,600);
 setTimeout(hh436BindViews,2000);
})();

// ===== v0.0.441 — binding GLOBAL das abas 01/02/03 (o antigo usa #viewHH, que não casa) =====
(function(){
 function hh441BindTabs(){
  document.querySelectorAll('[data-hh-tab]').forEach(function(b){
   if(b._hh441Bound)return;b._hh441Bound=true;
   b.addEventListener('click',function(e){
    e.stopPropagation();
    var key=b.getAttribute('data-hh-tab');
    document.querySelectorAll('[data-hh-tab]').forEach(function(x){var on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-selected',on?'true':'false');});
    [['programacao','hhPanelPlan'],['apontamento','hhPanelEntry'],['monitoramento','hhPanelMonitor']].forEach(function(pair){
     var el=document.getElementById(pair[1]);if(!el)return;var on=pair[0]===key;
     el.classList.toggle('active',on);el.hidden=!on;
    });
    try{hhRender();}catch(e3){}
    if(key==='monitoramento'&&window.echarts&&typeof hhChart!=='undefined'&&hhChart)setTimeout(function(){hhChart.resize();},80);
   });
  });
 }
 hh441BindTabs();
 setTimeout(hh441BindTabs,600);
 setTimeout(hh441BindTabs,2000);
})();

